8:import java.math.BigDecimal;
9:
10:/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
11:public final class ReservationService {
12:
13:    static final String HOTEL_NAME = "Pousada Maré Alta";
14:
15:    private final Rooms rooms;
16:    private final ReservationStore store;
17:    private final PriceCalculator priceCalculator;
18:    private final EmailSender emailSender;
19:    private final ReservationNotifications notifications;
20:
21:    public ReservationService(
22:            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender,
23:            ReservationNotifications notifications) {
24:        this.rooms = rooms;
25:        this.store = store;
26:        this.priceCalculator = priceCalculator;
27:        this.emailSender = emailSender;
28:        this.notifications = notifications;
29:    }
30:
31:    public synchronized Reservation create(NewReservation request) {
32:        if (!request.checkOut().isAfter(request.checkIn())) {
33:            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
34:        }
35:        if (request.guests() < 1) {
36:            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
37:        }
38:        Room room = rooms.find(request.roomNumber())
39:                .orElseThrow(() -> new HotelException(
40:                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
41:        if (request.guests() > room.capacity()) {
42:            throw new HotelException(
43:                    ErrorCode.CAPACITY_EXCEEDED,
44:                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
45:        }
46:        boolean roomTaken = store.all().stream()
47:                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
48:                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
49:        if (roomTaken) {
50:            throw new HotelException(
51:                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
52:        }
53:        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
54:        Reservation reservation = new Reservation(store.nextId(), request, price);
55:        store.save(reservation);
56:        return reservation;
57:    }
58:
59:    public Reservation find(long reservationId) {
60:        return store.find(reservationId)
61:                .orElseThrow(() -> new HotelException(
62:                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
63:    }
64:
65:    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
66:    public synchronized Reservation confirm(long reservationId) {
67:        Reservation reservation = find(reservationId);
68:        if (reservation.status() != ReservationStatus.PENDING) {
69:            throw notAllowed(reservation, "confirm");
70:        }
71:        reservation.confirmPayment();
72:        Room room = roomOf(reservation);
73:        ReservationReceipt receipt = new ReservationReceipt(reservation, room);
74:        emailSender.send(
75:                reservation.guest().email(),
76:                "Reserva confirmada - " + HOTEL_NAME,
77:                confirmationEmailBody(reservation, receipt));
78:        notifications.notifyConfirmed(reservation, room);
79:        return reservation;
80:    }
81:
82:    /**
83:     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
84:     * reservation was never paid, so nothing comes back).
85:     */
86:    public synchronized Reservation cancel(long reservationId) {
87:        Reservation reservation = find(reservationId);
88:        if (reservation.status() != ReservationStatus.PENDING
89:                && reservation.status() != ReservationStatus.CONFIRMED) {
90:            throw notAllowed(reservation, "cancel");
91:        }
92:        ReservationStatus previousStatus = reservation.status();
93:        BigDecimal refund = switch (reservation.ratePlan()) {
94:            case STANDARD -> reservation.amountPaid();
95:            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
96:        };
97:        reservation.cancel(refund);
98:        notifications.notifyCancelled(reservation, roomOf(reservation), refund, previousStatus);
99:        return reservation;
100:    }
101:
102:    public synchronized Reservation checkIn(long reservationId) {
103:        Reservation reservation = find(reservationId);
104:        if (reservation.status() != ReservationStatus.CONFIRMED) {
105:            throw notAllowed(reservation, "check in");
106:        }
107:        reservation.changeStatus(ReservationStatus.CHECKED_IN);
108:        return reservation;
109:    }
110:
111:    /** The guest leaves: the stay is closed and the final receipt is handed over. */
112:    public synchronized ReservationReceipt checkOut(long reservationId) {
113:        Reservation reservation = find(reservationId);
114:        if (reservation.status() != ReservationStatus.CHECKED_IN) {
115:            throw notAllowed(reservation, "check out");
116:        }
117:        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
118:        return new ReservationReceipt(reservation, roomOf(reservation));
119:    }
120:
121:    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
122:    public ReservationReceipt receiptCopy(long reservationId) {
123:        Reservation reservation = find(reservationId);
124:        if (!reservation.isPaid()) {
125:            throw notAllowed(reservation, "issue a receipt for");
126:        }
127:        return new ReservationReceipt(reservation, roomOf(reservation));
128:    }
129:
130:    private Room roomOf(Reservation reservation) {
131:        return rooms.find(reservation.roomNumber()).orElseThrow();
132:    }
133:
134:    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
135:        return "Olá, " + reservation.guest().name() + "!\n\n"
136:                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
137:                + receipt.text() + "\n"
138:                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
139:                + "Até breve!\n";
140:    }
